import sys, unicodedata, encodings.idna, json, inspect, platform, hashlib
texts=['', 'abc', 'ABC.', '.', '..', 'a..b', 'bücher.example', 'a。b．c｡', '\ud800.a', 'a.\udfff', '\u00ad.x', 'א.a', 'a.'+'x'*64, 'x'*64+'.', 'a\u200d.b', 'xn--abc-.x']
rows=[]
def fault(e):
 d={'name':type(e).__name__,'message':str(e),'suppressContext':e.__suppress_context__}
 if isinstance(e,(UnicodeEncodeError,UnicodeDecodeError)):
  d.update(encoding=e.encoding,object=list(e.object) if isinstance(e.object,bytes) else list(map(ord,e.object)),start=str(e.start),end=str(e.end),reason=e.reason)
 if e.__context__ is not None:d['context']=fault(e.__context__)
 return d
for text in texts:
 for end in range(len(text)+1):
  for final in [False,True]:
   for errors in ['strict','ignore']:
    value=text[:end]; row=dict(input=list(map(ord,value)),errors=errors,final=final)
    try:
     output,consumed=encodings.idna.IncrementalEncoder()._buffer_encode(value,errors,final)
     row.update(result=list(output),consumed=consumed)
    except Exception as e:row['error']=fault(e)
    rows.append(row)
print(json.dumps(dict(oracle=dict(version=sys.version,unicode=unicodedata.unidata_version,platform=platform.platform(),byteorder=sys.byteorder,module_sha256=hashlib.sha256(open(encodings.idna.__file__,"rb").read()).hexdigest()),source=inspect.getsource(encodings.idna.IncrementalEncoder),generator=open(__file__).read(),cases=rows),ensure_ascii=True,indent=2))
